package com.lbos.commercecustomer.service; import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.dto.client.partner.RetailerContextResponse;import com.lbos.commercecustomer.dto.request.StockAdjustmentRequest;import com.lbos.commercecustomer.entity.Product;import com.lbos.commercecustomer.enums.InventoryStatus;import com.lbos.commercecustomer.enums.StockAdjustmentType;import com.lbos.commercecustomer.exception.InsufficientStockException;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.ProductRepository;import com.lbos.commercecustomer.service.impl.*;import java.util.*;import org.junit.jupiter.api.*; @TestInstance(TestInstance.Lifecycle.PER_METHOD) class InventoryServiceImplTest {ProductRepository repo=mock(ProductRepository.class);ContextSupport ctx=mock(ContextSupport.class);InventoryServiceImpl service=new InventoryServiceImpl(repo,ctx,new CommerceMapper());@BeforeEach void setup(){when(ctx.retailer()).thenReturn(new RetailerContextResponse(UUID.randomUUID(),UUID.randomUUID(),"R",UUID.randomUUID()));}@Test void addPositive(){when(repo.addStock(anyLong(),any(),eq(5))).thenReturn(1);Product p=new Product();p.setId(1L);p.setStock(15);when(repo.findByIdAndRetailerId(anyLong(),any())).thenReturn(Optional.of(p));assertEquals(15,service.adjust(new StockAdjustmentRequest(1L,StockAdjustmentType.ADD_STOCK,5)).resultingQuantity());}@Test void removeNegativeInsufficient(){when(repo.removeStock(anyLong(),any(),eq(11))).thenReturn(0);assertThrows(InsufficientStockException.class,()->service.adjust(new StockAdjustmentRequest(1L,StockAdjustmentType.REMOVE_STOCK,11)));}@Test void boundaryLowStockTen(){Product p=new Product();p.setId(1L);p.setStock(10);when(repo.addStock(anyLong(),any(),eq(1))).thenReturn(1);when(repo.findByIdAndRetailerId(anyLong(),any())).thenReturn(Optional.of(p));assertEquals(InventoryStatus.LOW_STOCK,service.adjust(new StockAdjustmentRequest(1L,StockAdjustmentType.ADD_STOCK,1)).inventoryStatus());}}